local function dumpInstance(instance, log, indent)
    indent = indent or S(71)
    for _, child in ipairs(instance:GetChildren()) do
        local line = indent .. child.ClassName .. S(147) .. child.Name .. S(66)
        if child:IsA(S(29)) then
            line = line .. string.format(
                S(26),
                child.ActionText, child.ObjectText, tostring(child.HoldDuration)
            )
        elseif child:IsA(S(18)) then
            line = line .. string.format(S(74), tostring(child.MaxActivationDistance))
        elseif child:IsA(S(109)) or child:IsA(S(95)) then
            line = line .. S(156)
        end
        log(line)
        dumpInstance(child, log, indent .. S(31))
    end
end
return dumpInstance
end
