local Players = game:GetService(S(105))
local Workspace = game:GetService(S(132))
local function getCurrentPlot()
    local player = Players.LocalPlayer
    local mineWorld = Workspace:FindFirstChild(S(14))
    local plots = mineWorld and mineWorld:FindFirstChild(S(99))
    if not plots then
        return nil
    end
    for _, plot in ipairs(plots:GetChildren()) do
        if plot:GetAttribute(S(35)) == player.UserId then
            return plot
        end
    end
    return nil
end
return getCurrentPlot
end
